static int longestAtMost(int[] nums, int limit) {
    int left = 0, total = 0, best = 0;
    for (int right = 0; right < nums.length; right++) {
        total += nums[right];
        while (total > limit) {
            total -= nums[left];
            left++;
        }
        best = Math.max(best, right - left + 1);
    }
    return best;
}

