int longestAtMost(const std::vector<long long>& nums, long long limit) {
    int left = 0, best = 0;
    long long total = 0;
    for (int right = 0; right < (int)nums.size(); right++) {
        total += nums[right];
        while (total > limit) {
            total -= nums[left];
            left++;
        }
        best = std::max(best, right - left + 1);
    }
    return best;
}
